def create_drafting_user(apps, schema_editor):
    """Ruling P1: inactive system user that owns drafted entries (created_by)."""
    from django.contrib.auth.hashers import make_password
    User = apps.get_model('auth', 'User')
    StaffProfile = apps.get_model('users', 'StaffProfile')
    user, _ = User.objects.get_or_create(
        username='gl-drafting',
        defaults={'is_active': False, 'password': make_password(None)})
    StaffProfile.objects.get_or_create(user=user, defaults={'role': 'viewer'})


